#include <vector>
#include <map>
#include <set>
#include <string>
#include <algorithm>
struct Row{int id,owner,created,amount;};
std::vector<Row> query(const std::vector<Row>&rows,const std::vector<std::pair<int,int>>&friends,int owner,int depth,int minCreated,int maxCreated,int minAmount,std::string model,bool ownerIndex){std::map<int,std::vector<Row>>groups;std::map<int,std::vector<int>>adj;std::map<int,Row>kv;for(auto r:rows){groups[r.owner].push_back(r);kv.insert_or_assign(r.id,r);}for(auto& [key,list]:groups)std::sort(list.begin(),list.end(),[](auto a,auto b){return a.created!=b.created?a.created<b.created:a.id<b.id;});for(auto [a,b]:friends)adj[a].push_back(b);std::set<int>owners{owner};std::vector<std::pair<int,int>>queue{{owner,0}};for(unsigned head=0;head<queue.size();head++){auto [o,d]=queue[head];if(d>=depth)continue;std::vector<int>neighbors;if(model=="graph")neighbors=adj[o];else for(auto [a,b]:friends)if(a==o)neighbors.push_back(b);for(int n:neighbors)if(owners.insert(n).second)queue.push_back({n,d+1});}std::vector<Row>candidates;if(model=="document"||model=="graph"||model=="wide-column"||ownerIndex){for(int o:owners){const auto& group=groups[o];auto begin=group.begin(),end=group.end();if(model=="wide-column"){begin=std::lower_bound(group.begin(),group.end(),minCreated,[](auto r,int value){return r.created<value;});end=std::upper_bound(begin,group.end(),maxCreated,[](int value,auto r){return value<r.created;});}for(auto it=begin;it!=end;it++)candidates.push_back(model=="key-value"?kv.at(it->id):*it);}}else candidates=rows;std::vector<Row>out;for(auto r:candidates)if(owners.count(r.owner)&&r.created>=minCreated&&r.created<=maxCreated&&r.amount>=minAmount)out.push_back(r);std::sort(out.begin(),out.end(),[](auto a,auto b){return a.id<b.id;});return out;}
// Read-only fixture; owner indexes and adjacency are constructed explicitly, not supplied magically.
